const WeatherService={cacheKey:"advisoros_weather_cache",cacheTtlMs:18e5,async getTodayWeather(){const e=Utils.formatDate(Utils.getToday(),"iso");try{const t=JSON.parse(localStorage.getItem(this.cacheKey)||"null");if(t&&t.dateKey===e&&Date.now()-t.fetchedAt<this.cacheTtlMs)return t.data}catch{}const n=await this.resolveCoords();if(!n)return null;try{const t=await this.fetchCurrent(n);return localStorage.setItem(this.cacheKey,JSON.stringify({dateKey:e,fetchedAt:Date.now(),data:t})),t}catch(t){return void 0,null}},async resolveCoords(){const e=CONFIG.businessLatLng;return Array.isArray(e)&&e.length===2&&Number.isFinite(e[0])&&Number.isFinite(e[1])?{lat:e[0],lng:e[1]}:e&&Number.isFinite(e.lat)&&Number.isFinite(e.lng)?{lat:e.lat,lng:e.lng}:null},async fetchCurrent(e){var i,o;const n=`https://api.open-meteo.com/v1/forecast?latitude=${e.lat}&longitude=${e.lng}&current=temperature_2m,weather_code&temperature_unit=celsius&timezone=auto`,t=new AbortController,c=setTimeout(()=>t.abort(),5e3);try{const a=await fetch(n,{signal:t.signal});if(!a.ok)throw new Error(`Weather API returned ${a.status}`);const r=await a.json(),s=Math.round((i=r==null?void 0:r.current)==null?void 0:i.temperature_2m),u=(o=r==null?void 0:r.current)==null?void 0:o.weather_code;if(!Number.isFinite(s))throw new Error("Weather API returned no temperature");return{tempC:s,icon:this.iconForCode(u)}}finally{clearTimeout(c)}},iconForCode(e){return e===0?"wb_sunny":[1,2,3].includes(e)?"wb_cloudy":[45,48].includes(e)?"foggy":[51,53,55,56,57].includes(e)?"grain":[61,63,65,66,67,80,81,82].includes(e)?"rainy":[71,73,75,77,85,86].includes(e)?"ac_unit":[95,96,99].includes(e)?"thunderstorm":"wb_cloudy"}};